package com.bcsystems.siga.service;
import com.bcsystems.siga.domain.Nomina; import com.bcsystems.siga.exception.NotFoundException; import com.bcsystems.siga.repository.NominaRepository; import com.itextpdf.kernel.pdf.*; import com.itextpdf.kernel.geom.PageSize; import com.itextpdf.layout.Document; import com.itextpdf.layout.element.AreaBreak; import com.itextpdf.layout.element.Cell; import com.itextpdf.layout.element.Paragraph; import com.itextpdf.layout.element.Table; import com.itextpdf.layout.properties.TextAlignment; import com.itextpdf.layout.properties.UnitValue; import java.io.*; import java.util.List; import org.springframework.stereotype.Service;
@Service
public class NominaPdfService {
 private final NominaRepository repo; private final NominaService service;
 public NominaPdfService(NominaRepository r,NominaService s){repo=r;service=s;}
 public byte[] generar(Long id){Nomina n=repo.findById(id).orElseThrow(()->new NotFoundException("Nómina no encontrada"));try{ByteArrayOutputStream out=new ByteArrayOutputStream();PdfWriter w=new PdfWriter(out);PdfDocument pdf=new PdfDocument(w);Document d=new Document(pdf,PageSize.A6);d.add(new Paragraph("RECIBO DE NÓMINA").setBold().setTextAlignment(TextAlignment.CENTER));d.add(new Paragraph("Empleado: "+n.getPersona().getNombre()+" "+n.getPersona().getApellido()));d.add(new Paragraph("Periodo: "+n.getFechaInicio()+" al "+n.getFechaFin()));Table t=new Table(UnitValue.createPercentArray(new float[]{65,35})).useAllAvailableWidth();row(t,"Sueldo base",n.getSueldoBase());row(t,"Comisiones",n.getTotalComisiones());row(t,"Deducciones",n.getTotalDeducciones());row(t,"NETO",n.getSueldo());d.add(t);d.add(new Paragraph("Firma del empleado: ____________________"));d.add(new Paragraph("Firma del responsable: __________________"));d.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("No se pudo generar el recibo",e);}}
 public byte[] generarLote(List<Long> ids){try{ByteArrayOutputStream out=new ByteArrayOutputStream();PdfDocument pdf=new PdfDocument(new PdfWriter(out));Document d=new Document(pdf,PageSize.A6);for(int i=0;i<ids.size();i++){if(i>0)d.add(new AreaBreak());Nomina n=repo.findById(ids.get(i)).orElseThrow();d.add(new Paragraph("RECIBO DE NÓMINA").setBold().setTextAlignment(TextAlignment.CENTER));d.add(new Paragraph("Empleado: "+n.getPersona().getNombre()+" "+n.getPersona().getApellido()));d.add(new Paragraph("Periodo: "+n.getFechaInicio()+" al "+n.getFechaFin()));d.add(new Paragraph("Sueldo base: $"+n.getSueldoBase()));d.add(new Paragraph("Comisiones: $"+n.getTotalComisiones()));d.add(new Paragraph("Deducciones: $"+n.getTotalDeducciones()));d.add(new Paragraph("NETO: $"+n.getSueldo()));d.add(new Paragraph("Firma: ______________________________"));}d.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("No se pudo generar el lote PDF",e);}}
 private void row(Table t,String label,Object v){t.addCell(new Cell().add(new Paragraph(label)));t.addCell(new Cell().add(new Paragraph(String.valueOf(v==null?0:v))));}
}
